#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

static int parse_long(const char *s, long long *out) {
    char *endptr = NULL;
    errno = 0;
    long long v = strtoll(s, &endptr, 10);
    if (errno != 0) return 0;
    if (endptr == s) return 0;
    if (*endptr != '\0') return 0;
    *out = v;
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    long long x;
    if (!parse_long(argv[1], &x)) {
        puts("BAD_INPUT");
        return 0;
    }
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }
    if (x < -10 || x > 10) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    int coeff_cnt = argc - 2;
    long long coeff[coeff_cnt];
    for (int i = 0; i < coeff_cnt; ++i) {
        long long v;
        if (!parse_long(argv[2 + i], &v)) {
            puts("BAD_INPUT");
            return 0;
        }
        if (v < -1000 || v > 1000) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        coeff[i] = v;
    }
    long long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeff[i];
    }
    printf("%lld\n", result);
    return 0;
}
